import AppKit

struct FXSettings:Codable,Equatable {
    var preset=0,size=50,decay=10,predelay=0,damping=76,width=100,reverbLevel=55
    var division=3,feedback=43,delayDamping=65,delayLevel=70,pingpong=true
    static let presets=["Room","Hall","Plate","Chamber","Ambient","Custom"]
    static let divisions=["1/32","1/16","1/8","1/8 dotted","1/4","1/2","1 bar"]
    static func preset(_ index:Int)->FXSettings {var f=FXSettings();f.preset=index;switch index{case 1:f.size=90;f.decay=45;f.predelay=28;f.damping=45;f.reverbLevel=72;f.width=125;case 2:f.size=68;f.decay=28;f.predelay=12;f.damping=20;f.reverbLevel=68;case 3:f.size=58;f.decay=20;f.predelay=15;f.damping=55;f.reverbLevel=65;case 4:f.size=100;f.decay=90;f.predelay=45;f.damping=30;f.reverbLevel=80;f.width=145;default:break};return f}
    var valid:Bool{(0...5).contains(preset)&&(0...100).contains(size)&&(1...120).contains(decay)&&(0...250).contains(predelay)&&(0...100).contains(damping)&&(0...150).contains(width)&&(0...100).contains(reverbLevel)&&(0...6).contains(division)&&(0...90).contains(feedback)&&(0...100).contains(delayDamping)&&(0...100).contains(delayLevel)}
    func publish(){tm_fx_settings(Int32(size),Int32(decay),Int32(predelay),Int32(damping),Int32(width),Int32(reverbLevel),Int32(division),Int32(feedback),Int32(delayDamping),Int32(delayLevel),pingpong ? 1:0)}
    func tailSeconds(bpm:Double)->Double{let delayTime=[0.125,0.25,0.5,0.75,1,2,4][division]*60/bpm;let repeats=feedback>0 ? log(0.001)/log(Double(feedback)/100):1;return min(30,max(2,Double(decay)/10+Double(predelay)/1000+1,delayTime*repeats+0.5))}
}
extension Tracker {
    var fxSettings:FXSettings{project.fxSettings ?? FXSettings()}
    func updateFX(_ f:FXSettings){guard f.valid else{return};checkpoint();project.fxSettings=f;f.publish();needsDisplay=true}
    func chooseFXPreset(_ d:Int){let current=fxSettings;let next=(min(current.preset,4)+d+5)%5;var f=FXSettings.preset(next);f.division=current.division;f.feedback=current.feedback;f.delayDamping=current.delayDamping;f.delayLevel=current.delayLevel;f.pingpong=current.pingpong;updateFX(f)}
    func fxRows()->[(String,String,Int,Int,Int)]{let f=fxSettings;return [("Preset",FXSettings.presets[f.preset],f.preset,0,5),("Size","\(f.size)%",f.size,0,100),("Decay",String(format:"%.1f s",Double(f.decay)/10),f.decay,1,120),("Pre-delay","\(f.predelay) ms",f.predelay,0,250),("Damping","\(f.damping)%",f.damping,0,100),("Stereo width","\(f.width)%",f.width,0,150),("Return level","\(f.reverbLevel)%",f.reverbLevel,0,100),("Time",FXSettings.divisions[f.division],f.division,0,6),("Feedback","\(f.feedback)%",f.feedback,0,90),("Damping","\(f.delayDamping)%",f.delayDamping,0,100),("Return level","\(f.delayLevel)%",f.delayLevel,0,100),("Mode",f.pingpong ? "Ping-pong":"Stereo",f.pingpong ? 1:0,0,1)]}
    func adjustFX(_ d:Int){if fxFocus==0{chooseFXPreset(d>0 ? 1:-1);return};let r=fxRows()[fxFocus];let v=min(r.4,max(r.3,r.2+d));var f=fxSettings;switch fxFocus{case 1:f.size=v;case 2:f.decay=v;case 3:f.predelay=v;case 4:f.damping=v;case 5:f.width=v;case 6:f.reverbLevel=v;case 7:f.division=v;case 8:f.feedback=v;case 9:f.delayDamping=v;case 10:f.delayLevel=v;case 11:f.pingpong=v==1;default:break};if fxFocus<7{f.preset=5};updateFX(f)}
    func fxSoft(_ i:Int){switch i{case 0:chooseFXPreset(-1);case 1:chooseFXPreset(1);case 2:fxFocus=0;case 3:fxFocus=7;case 4:if fxFocus==16{updateDynamics(DynamicsSettings())}else if fxFocus>=12{resetEQ()}else{updateFX(FXSettings())};case 5:openDynamics();case 6:fxFocus=12;needsDisplay=true;case 7:selectPage(3);default:break}}
    func fxKey(_ event:NSEvent)->Bool{if fxFocus==16{return dynamicsKey(event)};if event.charactersIgnoringModifiers?.lowercased()=="c"{openDynamics();return true};if fxFocus>=12{return eqKey(event)};let code=event.keyCode,ch=event.charactersIgnoringModifiers?.lowercased() ?? "",d=event.modifierFlags.contains(.shift) ? 10:1;if ch=="a"{fxFocus=12;needsDisplay=true;return true};switch code{case 126:fxFocus=max(fxFocus>=7 ? 7:0,fxFocus-1);case 125:fxFocus=min(fxFocus>=7 ? 11:6,fxFocus+1);case 123:fxFocus=0;case 124:fxFocus=7;case 48:fxFocus=fxFocus>=7 ? 12:7;case 53:selectPage(3);case 36,76:if fxFocus==0{chooseFXPreset(1)}else if fxFocus==11{adjustFX(fxSettings.pingpong ? -1:1)};default:if ch=="q"{adjustFX(-d)}else if ch=="e"{adjustFX(d)}else{return false}};return true}
    func drawFXPage(){if fxFocus==16{drawDynamics();return};if fxFocus>=12{drawEQ();return};let w=bounds.width,col=(w-130)/2;txt("FX SETTINGS / GLOBAL SENDS",55,65,12,teal,true);txt("Reverb (v) / Delay (d) in FX1 or FX2 controls per-step send. These settings shape their shared returns.",55,95,12,gray(0.85));let rows=fxRows();let rh=min(58,max(26,(footerY-162)/7));for i in rows.indices{let second=i>=7,j=second ? i-7:i,x=second ? 65+col:55,y=150+CGFloat(j)*rh;let r=rows[i];rect(x,y,col-15,rh-4,i==fxFocus ? gray(0.33):gray(0.19));if i==fxFocus{border(x,y,col-15,rh-4,teal)};txt(r.0,x+12,y+8,12,gray(0.85),true);txt(r.1,x+col*0.45,y+8,12,i==fxFocus ? teal:yellow,true);if i != 0 && i != 7 && i != 11 {let bw=max(30,col*0.20);rect(x+col*0.73,y+rh/2-3,bw,6,gray(0.38));rect(x+col*0.73,y+rh/2-3,bw*CGFloat(r.2-r.3)/CGFloat(max(1,r.4-r.3)),6,teal)}};txt("REVERB",55,128,12,purple,true);txt("DELAY",65+col,128,12,purple,true);txt("↑ ↓ parameter   ← → / Tab section   Q/E value   Shift fast   A EQ graph   C Dynamics   Space playback   Esc Mixer",55,footerY-25,12,gray(0.7))}
    func fxMouse(_ p:NSPoint)->Bool{if fxFocus==16{return dynamicsMouse(p)};if fxFocus>=12{let x:CGFloat=56,gw=bounds.width-112;fxFocus=12+max(0,min(3,Int((p.x-x)/(gw/4))));needsDisplay=true;return true};let w=bounds.width,col=(w-130)/2,rh=min(58,max(26,(footerY-162)/7));guard p.y>=150&&p.y<footerY-25 else{return false};let right=p.x>=65+col,i=Int((p.y-150)/rh)+(right ? 7:0);if (right ? 7...11:0...6).contains(i){fxFocus=i;needsDisplay=true;return true};return false}
}
